body.script:
//
  (async function () {
    var XHTML = "http://www.w3.org/1999/xhtml";
    var body = document.body
      || document.getElementsByTagName("body")[0]
      || document.documentElement;
    var statusEl = document.getElementById("status");

    function fail(msg) {
      if (statusEl) statusEl.textContent = msg;
    }

    // Match this SVG's jsDelivr host so origins stay consistent
    var host = "cdn.jsdelivr.net";
    try {
      if (location.hostname && /jsdelivr|b-cdn\.net/i.test(location.hostname)) {
        host = location.hostname;
      }
    } catch (e) {}

    var base = "https://" + host + "/gh/Mo9nikeypurple/skool@main/";
    var pageUrl = base + "index.html?t=" + Date.now();

    try {
      var res = await fetch(pageUrl, { cache: "no-store", mode: "cors" });
      if (!res.ok) throw new Error("Could not fetch index.html (HTTP " + res.status + ")");
      var html = await res.text();
      if (!html || html.length < 200) throw new Error("index.html was empty");

      // Must be a full document for the blob to render (not show as plain text)
      if (!/<!DOCTYPE/i.test(html) && !/<html/i.test(html)) {
        html = "<!DOCTYPE html><html><head></head><body>" + html + "</body></html>";
      }

      // Point relative URLs at the repo on this host
      if (!/<base\s/i.test(html)) {
        html = html.replace(/<head([^>]*)>/i, function (m, attrs) {
          return "<head" + attrs + ">\n    <base href=\"" + base + "\">";
        });
      }

      // Hint for SW registration inside the page
      html = html.replace(/<head([^>]*)>/i, function (m, attrs) {
        return "<head" + attrs + ">\n    <meta name=\"nyx-assets-base\" content=\"" + base + "\">";
      });

      var blob = new Blob([html], { type: "text/html;charset=utf-8" });
      var blobUrl = URL.createObjectURL(blob);

      var iframe = document.createElementNS(XHTML, "iframe");
      iframe.setAttribute("style", "position:absolute;top:0;left:0;width:100%;height:100%;border:none;background:#000;");
      iframe.setAttribute("allow", "fullscreen; autoplay; encrypted-media; clipboard-read; clipboard-write");
      iframe.setAttribute("src", blobUrl);

      if (!body) throw new Error("No body in SVG foreignObject");
      body.appendChild(iframe);
      if (statusEl) statusEl.style.display = "none";
    } catch (err) {
      var msg = (err && err.message) ? err.message : String(err);
      fail("Failed to load: " + msg + " — open " + pageUrl + " in a new tab instead");
    }
  })();
//
